from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class GetAntennaParametersResponseFile(SchemaObject):
    file_name = SchemaField(name='file_name', optional=True)
    file_index = SchemaField(name='file_index', optional=True)
    file_type = SchemaField(name='file_type', optional=True)

    def __init__(self, file_name, file_index, file_type):
        self.file_name = file_name
        self.file_index = file_index
        self.file_type = file_type

        super(GetAntennaParametersResponseFile, self).__init__()


class GetAntennaParametersResponseFrequency(SchemaObject):
    low = SchemaField(name='low', optional=True)
    high = SchemaField(name='high', optional=True)

    def __init__(self, low, high):
        self.low = low
        self.high = high

        super(GetAntennaParametersResponseFrequency, self).__init__()


class AntennaParameters(SchemaObject):
    file_information = SchemaField(name='file_information')
    file_version = SchemaField(name='file_version')
    num_of_electrical_tilt_samples = SchemaField(name='num_of_electrical_tilt_samples',)
    electrical_tilt = SchemaField(name='electrical_tilt', many=True)
    num_of_broadcast_beam_widths = SchemaField(name='num_of_broadcast_beam_widths')
    broadcast_beam_width = SchemaField(name='broadcast_beam_width', many=True)
    num_of_frequency_bands = SchemaField(name='num_of_frequency_bands')
    frequencies = SchemaField(name='frequencies', many=True, klass=GetAntennaParametersResponseFrequency)
    num_of_rf_ports = SchemaField(name='num_of_rf_ports')
    antenna_advanced_parameters = SchemaField(name='antenna_advanced_parameters')

    def __init__(self, file_information, file_version, num_of_electrical_tilt_samples, electrical_tilt,
                 num_of_broadcast_beam_widths, broadcast_beam_width, num_of_frequency_bands, frequencies,
                 num_of_rf_ports, antenna_advanced_parameters):
        self.file_information = file_information
        self.file_version = file_version
        self.num_of_electrical_tilt_samples = num_of_electrical_tilt_samples
        self.electrical_tilt = electrical_tilt
        self.num_of_broadcast_beam_widths = num_of_broadcast_beam_widths
        self.broadcast_beam_width = broadcast_beam_width
        self.num_of_frequency_bands = num_of_frequency_bands
        self.frequencies = frequencies
        self.num_of_rf_ports = num_of_rf_ports
        self.antenna_advanced_parameters = antenna_advanced_parameters

        super(AntennaParameters, self).__init__()


class GetAntennaParametersResponse(SchemaObject):
    file = SchemaField(name='file', optional=True, many=True, klass=GetAntennaParametersResponseFile)
    frequency = SchemaField(name='frequency', optional=True, many=True, klass=GetAntennaParametersResponseFrequency)
    weight_info = SchemaField(name='weight_info', optional=True)
    weight_file_name = SchemaField(name='weight_file_name', optional=True)
    version = SchemaField(name='version', optional=True)
    format_version = SchemaField(name='format_version', optional=True)
    advanced_params = SchemaField(name='advanced_params', optional=True)
    antenna_parameters1d = SchemaField(name='antenna_parameters1d', optional=True,
                                       klass=AntennaParameters)

    def __init__(self, file, frequency, weight_info, weight_file_name, version, format_version, advanced_params,
                 antenna_parameters1d):
        self.file = file
        self.frequency = frequency
        self.weight_info = weight_info
        self.weight_file_name = weight_file_name
        self.version = version
        self.format_version = format_version
        self.advanced_params = advanced_params
        self.antenna_parameters1d = antenna_parameters1d

        super(GetAntennaParametersResponse, self).__init__()
